SELECT 'gongkao', '组合计算', 'kp-xingce-data-analysis-combined-calc', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "组合计算"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "要求对材料中多个散落数据进行加减合并后再做最终除法的综合运算题。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "选项里出现：“2023年第一、二、三产业的总增量为多少？”或者“东部与西部地区人均收入的差距是？” 这种题往往需要提取三个及以上的数据。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破局：合并同类项"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "如果要求多个项目的总量，且这几个项目的基准（分母或除数）相同，尽量先在分子层面做加法，最后只做一次除法。"}]}, {"type": "katexBlock", "attrs": {"content": "\\frac{A}{N} + \\frac{B}{N} + \\frac{C}{N} = \\frac{A+B+C}{N}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题目: 求总体平均或总体增量] --> B[寻找所有涉及的分支数据]\nB --> C{这些分支数据的基数/分母是否一致?}\nC -- 一致 --> D[在材料中直接把它们的绝对量先加减合并]\nD --> E[只拿最后的合并总数去做一次除法]\nC -- 不一致 --> F[只能老老实实单独计算后相加减]\nE --> G[截位直除出答案]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 材料给出 1月、2月、3月 的各自汽车产量为 100, 150, 140 万辆。求一季度的月均产量？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：求一季度月均，就是求前三个月的合并平均数。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "错误思路：100/1 + 150/1 + 140/1？这种题如果数字复杂，分母变成 1.15 的时候就崩溃了。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "合并同类项：总产量 = 100 + 150 + 140 = 390。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "最后只除一次：390 ÷ 3 = 130万辆。秒杀。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略了“其他”项：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "求“除东部地区外其他地区总产值”。材料给了全国总量 1000 亿，东部 600 亿，中部 200 亿，西部 150 亿。最快的算法是利用容斥原理：其他 = 全国 - 东部 = 1000 - 600 = 400。绝对不要去加 中部+西部，因为材料往往隐藏了东北地区没有单独列出，加起来会少算！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "做组合计算题前先深呼吸，问自己一句：“能不能用总数减法来代替长串的加法？”"}]}]}$$ AS jsonb), NULL, '组合计算的核心考点与实战推导。', category_node.id, CAST('["资料分析", "组合计算"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_combined_calc", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
